d_sd_t_ha","pnl.typical_profit","ins.crop_cover","ins.max_loss"]},{"riskId":"regulation","total":40000,"summary":"£40k a year of SFI payments, agreement ends 31 Mar 2027; 350 ha relies on glyphosate.","working":[{"label":"sfi_payments_a_year","value":"£40k"},{"label":"sfi_agreement_ends","value":"31 Mar 2027"},{"label":"per_month_without_payments = sfi ÷ 12","value":"£3.3k"},{"label":"delinked payment (phasing out, in expected profit)","value":"£9.6k"},{"label":"area_relying_on_glyphosate (no £ figure yet)","value":"350 ha"}],"sensitivities":[{"metric":"sfi_gap_months","label":"£40k a year of SFI payments","perUnit":-3333.3333333333335,"unit":"months"}],"fieldKeys":["schemes.sfi_annual","schemes.sfi_end","schemes.delinked","schemes.countryside_stewardship","reg.nvz","reg.glyphosate_ha","reg.assurance","pnl.typical_profit","ins.max_loss"]},{"riskId":"interest_rates","total":840000,"summary":"£840k of variable borrowing at Bank Rate + 3.1%; each 1-point rise costs £8.4k a year.","working":[{"label":"variable_debt","value":"£840k"},{"label":"margin_over_bank_rate","value":"3.1%"},{"label":"per_1pt_rise = variable_debt × 1%","value":"£8.4k"},{"label":"overdraft at peak (not counted until the limit is confirmed)","value":"£120k"}],"sensitivities":[{"metric":"bank_rate_pct","label":"£840k of variable debt","perUnit":-8400,"unit":"points"}],"fieldKeys":["fin.loan","fin.loan_rate_type","fin.loan_margin_pct","fin.loan_renewal","fin.lender","fin.overdraft_limit","fin.overdraft_peak","fin.capital_repayment","pnl.typical_profit","ins.max_loss"]}]'::jsonb);
insert into assessments (id, farm_id, snapshot_id, created_at, harvest_year, summary, risks) values
  ('00000000-0000-4000-8000-000000000002', 'fenland-ridge', '00000000-0000-4000-8000-000000000001', '2026-11-07T06:00:00Z', 2027, '{"meta":{"date":"2026-11-07","updatedAt":"06:00","harvestYear":2027,"typicalProfit":85000},"profit":{"expected":85000,"badYear":-90000,"goodYear":260000,"lossChance":0.21,"lossYearsOf20":4,"deltaWeek":-15000,"working":[{"label":"expected_profit (3-yr average, price-adjusted)","value":"£85k"},{"label":"output_prices_sd = £793k unsold × 11.4%","value":"£90k"},{"label":"other_risks_sd","value":"£55k"},{"label":"farm_sd = √(output_prices_sd² + other_risks_sd²)","value":"£106k"},{"label":"bad_year = expected − 1.65 × farm_sd","value":"−£90k"},{"label":"good_year = expected + 1.65 × farm_sd","value":"£260k"},{"label":"loss_chance = Φ(−expected ÷ farm_sd)","value":"21% (4 in 20)"},{"label":"change vs last week (wheat −£4/t on 2,898 t, AN +£18/t on 166 t)","value":"−£15k"}],"sources":[{"label":"Profit and loss 2023–2025","origin":"Accounts · Upload","date":"14 Oct 2026"},{"label":"Feed wheat, delivered: £178/t","origin":"AHDB delivered prices","date":"06 Nov 2026"},{"label":"AN price: £504/t","origin":"AHDB fertiliser prices","date":"Oct 2026"}]},"breakEvens":[{"crop":"Wheat","price":178,"breakEven":185,"unit":"t"},{"crop":"Spring barley","price":158,"breakEven":150,"unit":"t"},{"crop":"Oilseed rape","price":452,"breakEven":395,"unit":"t"}],"topMitigationIds":["wheat-minprice-half-2027","fert-buy-half","rates-compare-margin"]}'::jsonb, '[{"id":"output_prices","name":"Output prices","expected":14000,"trend7d":-2000,"driver":"£793k of wheat, barley and rape unsold","summary":"Almost none of your crop is sold: one bad price year for grain and rape would take more than a typical year''s profit.","reasoning":["Unsold crop is worth £793k at today''s prices: 1,028 t of 2026 wheat in store, and the whole 2027 crop of wheat, spring barley and oilseed rape.","Wheat, barley and rape prices swing about 11–12% a year and tend to move together, so they are treated as one exposure. A 1-in-20 bad year takes 18.8% off, about £149k.","Delivered feed wheat is £178/t, £7 under your £185/t break-even, so wheat is the part to act on first.","Wheat fell £4/t this week. That cut the value at stake by £12k and the bad-year hit by about £2k; the fall itself shows up in expected profit.","A minimum-price contract on half the 2027 wheat keeps the upside on that half and costs about £7.5k."],"sources":[{"label":"2026 wheat unsold: 1,028 t","origin":"Grain store sheet · Onboarding","date":"12 Oct 2026"},{"label":"2027 crop: wheat 1,870 t, barley 780 t, rape 340 t","origin":"Cropping plan · Onboarding","date":"12 Oct 2026"},{"label":"Feed wheat £178/t, feed barley £158/t, rape £452/t","origin":"AHDB delivered prices","date":"06 Nov 2026"},{"label":"Price swing: wheat 11.2%, barley 11.4%, rape 12.2% standard deviation","origin":"AHDB 10-yr history · Model"},{"label":"Wheat break-even: £185/t","origin":"Accounts 2025 · Upload","date":"14 Oct 2026"},{"label":"Minimum-price premium: ~£8/t","origin":"Merchant quote · via MCP","date":"05 Nov 2026"}],"model":{"exposure":793,"unit":"£k","unitSd":114,"otherSdK":55,"exposureLabel":"Crop value unsold","keys":{"exposure":"crop_value_unsold","sd":"price_sd","shock":"bad_price_fall"},"shockLabel":"Bad-year price fall","tradeoff":{"title":"How much of the 2027 crop to sell forward","actionLabel":"2027 crop sold forward","hedgeable":610,"note":"Share of the £610k 2027 crop (wheat, barley and rape at today''s prices). Before any options above."},"meanK":85},"mitigations":[{"id":"wheat-minprice-half-2027","title":"Minimum-price contract on half the 2027 wheat","description":"Sets a floor under 935 t (£166k at today''s price) while keeping any price rise. Premium about £8/t.","cost":"Premium ~£7.5k","status":"suggested","effect":{"unitsRemoved":166,"meanCost":7.5},"riskId":"output_prices","badYearReduction":31225,"scoreAfter":10},{"id":"wheat-sell-2026","title":"Sell 20% more of the 2026 wheat in store","description":"Move 374 t (£67k) from store at today''s £178/t before the 20 Nov movement date.","cost":"No premium · locks in £178/t","status":"suggested","effect":{"unitsRemoved":67},"riskId":"output_prices","badYearReduction":12603,"scoreAfter":10},{"id":"osr-forward-third","title":"Sell a third of the 2027 rape forward","description":"113 t (£51k) at today''s £452/t before the merchant''s offer expires on 15 Jan.","cost":"No premium · gives up upside on 113 t","status":"suggested","effect":{"unitsRemoved":51},"riskId":"output_prices","badYearReduction":9593,"scoreAfter":10},{"id":"wheat-forward-30","title":"Sell 30% of the 2027 wheat forward","description":"Fixed-price contract on 561 t (£100k) for harvest 2027 delivery.","cost":"No premium · gives up upside on 561 t","status":"suggested","effect":{"unitsRemoved":100},"riskId":"output_prices","badYearReduction":18810,"scoreAfter":10}],"badYear":149000,"score":10,"pctOfProfit":175,"working":[{"label":"crop_value_unsold","value":"£793k"},{"label":"price_sd","value":"11.4%"},{"label":"bad_price_fall = price_sd × 1.65","value":"18.8%"},{"label":"bad_year_hit = crop_value_unsold × bad_price_fall","value":"£149k"},{"label":"risk_sd = crop_value_unsold × price_sd","value":"£90k"},{"label":"other_risks_sd","value":"£55k"},{"label":"farm_sd = √(risk_sd² + other_risks_sd²)","value":"£106k"},{"label":"expected_profit","value":"£85k"},{"label":"bad_year_profit = expected_profit − 1.65 × farm_sd","value":"−£90k"},{"label":"loss_years = 20 × Φ(−expected_profit ÷ farm_sd)","value":"4 in 20"}]},{"id":"weather_yield","name":"Weather and yield","expected":9000,"trend7d":0,"driver":"Dry spring or wet harvest, all crops","summary":"A dry spring or wet harvest hits every crop at once, which makes this the hardest risk to offset.","reasoning":["All 450 ha are exposed to the same weather, so a bad season cuts wheat, barley and rape together.","Your five-year yield record swings about £78/ha either side of normal; a 1-in-20 season costs £58k.","Nothing changed this week: soil moisture is normal for the time of year.","Yield-index insurance on the wheat area is the main lever; splitting barley drilling helps at the margin."],"sources":[{"label":"Farmed area: 450 ha","origin":"RPA land parcels","date":"12 Oct 2026"},{"label":"Yield swing: £78/ha standard deviation","origin":"Yield records 2021–25 · Upload"},{"label":"Soil moisture: normal","origin":"Met Office · Lincs","date":"06 Nov 2026"},{"label":"Index insurance quote: ~£4.2k/yr","origin":"Broker quote · via MCP","date":"02 Nov 2026"}],"model":{"exposure":450,"unit":"ha","unitSd":78,"exposureLabel":"Hectares exposed","keys":{"exposure":"hectares_exposed","sd":"yield_sd_per_ha","shock":"bad_loss_per_ha"},"shockLabel":"Bad-year loss per hectare","tradeoff":{"title":"How much area to insure","actionLabel":"Area insured","hedgeable":450,"note":"Share of the 450 ha farmed. Index cover pays on regional yield, not your own."},"meanK":85,"otherSdK":99.8274090818749},"mitigations":[{"id":"weather-index-insurance","title":"Yield-index insurance on the wheat area","description":"Pays out when regional wheat yield falls below trend. Covers about 160 ha-equivalent.","cost":"Premium ~£4.2k/yr","status":"suggested","effect":{"unitsRemoved":160,"meanCost":4.2},"riskId":"weather_yield","badYearReduction":20592,"scoreAfter":5},{"id":"weather-split-drilling","title":"Split spring barley drilling across two windows","description":"Halves the chance that one dry spell catches the whole barley crop.","cost":"No direct cost · more planning","status":"planned","effect":{"unitsRemoved":60},"riskId":"weather_yield","badYearReduction":7722,"scoreAfter":6}],"badYear":58000,"score":7,"pctOfProfit":68,"working":[{"label":"hectares_exposed","value":"450 ha"},{"label":"yield_sd_per_ha","value":"£78/ha"},{"label":"bad_loss_per_ha = yield_sd_per_ha × 1.65","value":"£129/ha"},{"label":"bad_year_hit = hectares_exposed × bad_loss_per_ha","value":"£58k"},{"label":"risk_sd = hectares_exposed × yield_sd_per_ha","value":"£35k"},{"label":"other_risks_sd","value":"£100k"},{"label":"farm_sd = √(risk_sd² + other_risks_sd²)","value":"£106k"},{"label":"expected_profit","value":"£85k"},{"label":"bad_year_profit = expected_profit − 1.65 × farm_sd","value":"−£90k"},{"label":"loss_years = 20 × Φ(−expected_profit ÷ farm_sd)","value":"4 in 20"}]},{"id":"input_prices","name":"Input prices","expected":4000,"trend7d":1000,"driver":"166 t nitrogen, 60% of diesel and half of sprays unbought","summary":"£121k of spring inputs is still unbought, most of it nitrogen, so a price spike before spring lands straight on margin.","reasoning":["Your agronomist''s plan needs 166 t of ammonium nitrate for spring (£84k at £504/t); none is bought yet.","22,800 L of the year''s 38,000 L of diesel (£16k) and half the £43k spray budget (£22k) are also unbought.","Nitrogen swings most, about 18% a year; diesel about 15% and sprays about 6%. A 1-in-20 year adds about £31k to the bill.","The hit rose £1k this week as AN went up £18/t with gas prices.","Buying half the nitrogen now removes a third of the exposure for roughly the interest on paying early."],"sources":[{"label":"Spring N needed: 166 t AN","origin":"Agronomist N plan · via MCP","date":"20 Oct 2026"},{"label":"Spring N bought: 0 t","origin":"Freshness check","date":"27 Sep 2026"},{"label":"Diesel: 38,000 L a year, 40% bought","origin":"Fuel invoices 2025 · Onboarding","date":"12 Oct 2026"},{"label":"Sprays: £96/ha budget, 50% bought","origin":"Agronomist plan · via MCP","date":"20 Oct 2026"},{"label":"AN £504/t, red diesel 68p/L","origin":"AHDB input prices","date":"Oct 2026"},{"label":"Price swing: AN 18%, diesel 15%, sprays 6% standard deviation","origin":"AHDB 10-yr history · Model"}],"model":{"exposure":121,"unit":"£k","unitSd":155,"exposureLabel":"Inputs unbought","keys":{"exposure":"inputs_unbought","sd":"price_sd","shock":"bad_price_rise"},"shockLabel":"Bad-year price rise","tradeoff":{"title":"How much of the spring inputs to buy now","actionLabel":"Inputs bought now","hedgeable":121,"note":"Share of the £121k of nitrogen, diesel and sprays still to buy. Buying early ties up cash until spring."},"meanK":85,"otherSdK":104.14303423177185},"mitigations":[{"id":"fert-buy-half","title":"Buy half of spring nitrogen now","description":"83 t at today''s £504/t (£42k), delivered in January.","cost":"~£0.6k interest on paying early","status":"suggested","effect":{"unitsRemoved":42,"meanCost":0.6},"riskId":"input_prices","badYearReduction":10742,"scoreAfter":3},{"id":"fert-fixed-pod","title":"Fixed price, pay on delivery for the rest of the nitrogen","description":"Ask the merchant to fix the other 83 t (£42k) now and invoice in March.","cost":"~£11/t above spot","status":"suggested","effect":{"unitsRemoved":42,"meanCost":0.9},"riskId":"input_prices","badYearReduction":10742,"scoreAfter":3},{"id":"diesel-fix","title":"Fix the price on the rest of the year''s diesel","description":"22,800 L (£16k) at about 69p/L, delivered as needed.","cost":"~1p/L above spot","status":"suggested","effect":{"unitsRemoved":16,"meanCost":0.2},"riskId":"input_prices","badYearReduction":4092,"scoreAfter":4}],"badYear":31000,"score":5,"pctOfProfit":36,"working":[{"label":"inputs_unbought","value":"£121k"},{"label":"price_sd","value":"15.5%"},{"label":"bad_price_rise = price_sd × 1.65","value":"25.6%"},{"label":"bad_year_hit = inputs_unbought × bad_price_rise","value":"£31k"},{"label":"risk_sd = inputs_unbought × price_sd","value":"£19k"},{"label":"other_risks_sd","value":"£104k"},{"label":"farm_sd = √(risk_sd² + other_risks_sd²)","value":"£106k"},{"label":"expected_profit","value":"£85k"},{"label":"bad_year_profit = expected_profit − 1.65 × farm_sd","value":"−£90k"},{"label":"loss_years = 20 × Φ(−expected_profit ÷ farm_sd)","value":"4 in 20"}]},{"id":"regulation","name":"Regulation","expected":4000,"trend7d":0,"driver":"SFI agreement ends March 2027","summary":"Your SFI agreement ends in March 2027 and nothing is lined up yet to replace the £40k a year.","reasoning":["Scheme payments bring in about £40k a year; the current SFI agreement ends on 31 March 2027.","If the next offer is delayed or smaller, about half of that could be missing in the 2027 harvest year.","The delinked payment (£9.6k this year) is already phasing out, so it is in expected profit rather than counted as a risk.","Rule changes without a £ figure yet, such as the glyphosate review and NVZ closed periods, are tracked as news against your profile.","An application in the next window would protect roughly half the income at stake."],"sources":[{"label":"SFI agreement: £40k/yr, ends 31 Mar 2027","origin":"RPA agreement PDF · Upload","date":"12 Oct 2026"},{"label":"Next offer window: expected Jan–Mar 2027","origin":"DEFRA announcement · Agent read","date":"28 Oct 2026"},{"label":"Delinked payment 2026: £9.6k, ends after 2027","origin":"RPA statement · Upload","date":"12 Oct 2026"},{"label":"Glyphosate approval review: decision due Dec 2026","origin":"HSE · Agent read","date":"01 Nov 2026"}],"model":{"exposure":40,"unit":"£k","unitSd":303,"exposureLabel":"Payments at risk","keys":{"exposure":"payments_at_risk","sd":"payment_sd","shock":"bad_year_shortfall"},"shockLabel":"Bad-year shortfall","tradeoff":{"title":"How much income to secure","actionLabel":"Payments secured","hedgeable":40,"note":"Share of the £40k a year at stake if the agreement is not replaced."},"meanK":85,"otherSdK":105.1219634710083},"mitigations":[{"id":"scheme-apply-next","title":"Apply for the next SFI offer before the agreement ends","description":"Line up actions that fit the rotation so payments carry on from April.","cost":"~£1.2k adviser time","status":"suggested","effect":{"unitsRemoved":20,"meanCost":1.2},"riskId":"regulation","badYearReduction":9999,"scoreAfter":2},{"id":"scheme-cs-check","title":"Check Countryside Stewardship Higher Tier eligibility","description":"Field margins along the drain may qualify.","cost":"Free · one call","status":"done","effect":{"unitsRemoved":6},"riskId":"regulation","badYearReduction":3000,"scoreAfter":3}],"badYear":20000,"score":3,"pctOfProfit":24,"working":[{"label":"payments_at_risk","value":"£40k"},{"label":"payment_sd","value":"30.3%"},{"label":"bad_year_shortfall = payment_sd × 1.65","value":"50.0%"},{"label":"bad_year_hit = payments_at_risk × bad_year_shortfall","value":"£20k"},{"label":"risk_sd = payments_at_risk × payment_sd","value":"£12k"},{"label":"other_risks_sd","value":"£105k"},{"label":"farm_sd = √(risk_sd² + other_risks_sd²)","value":"£106k"},{"label":"expected_profit","value":"£85k"},{"label":"bad_year_profit = expected_profit − 1.65 × farm_sd","value":"−£90k"},{"label":"loss_years = 20 × Φ(−expected_profit ÷ farm_sd)","value":"4 in 20"}]},{"id":"interest_rates","name":"Interest rates","expected":2000,"trend7d":-1000,"driver":"£840k variable at base + 3.1%","summary":"£840k of variable debt means every 1-point rise in Bank Rate costs about £8k a year.","reasoning":["All £840k of borrowing is variable at Bank Rate + 3.1%.","A 1-in-20 rise of 1.3 points over the year would cost about £11k.","Markets priced in slightly lower rates this week, so the hit eased by £1k.","The bigger win is the margin: well-secured farms pay 1.3–1.8% over base, worth about £11k a year to you."],"sources":[{"label":"Variable borrowing: £840k at base + 3.1%","origin":"Bank statement · Upload","date":"12 Oct 2026"},{"label":"Loan renewal: 14 May 2027","origin":"Bank facility letter · Upload","date":"12 Oct 2026"},{"label":"Typical secured farm margin: 1.3–1.8%","origin":"Lender survey · Agent read","date":"Oct 2026"},{"label":"Bank Rate expectations","origin":"Bank of England · Market curve","date":"06 Nov 2026"}],"model":{"exposure":840,"unit":"£k","unitSd":7.9,"exposureLabel":"Variable debt","keys":{"exposure":"variable_debt","sd":"rate_sd","shock":"bad_rate_rise"},"shockLabel":"Bad-year rate rise","tradeoff":{"title":"How much of the loan to fix","actionLabel":"Loan fixed","hedgeable":840,"note":"Share of the £840k fixed for three years. Fixing gives up savings if rates fall."},"meanK":85,"otherSdK":105.61006158505921},"mitigations":[{"id":"rates-compare-margin","title":"Compare lender margin before May renewal","description":"You pay base + 3.1%; well-secured farms pay 1.3–1.8%.","cost":"Free · a few calls","status":"suggested","benefitKind":"profit","badYearReduction":10920,"effect":{"meanCost":-10.9},"riskId":"interest_rates","scoreAfter":2},{"id":"rates-fix-half","title":"Fix half the £840k for three years","description":"Swaps half the variable exposure for a fixed rate at renewal.","cost":"~£2.1k/yr above variable today","status":"suggested","effect":{"unitsRemoved":420,"meanCost":2.1},"riskId":"interest_rates","badYearReduction":5475,"scoreAfter":1}],"badYear":11000,"score":2,"pctOfProfit":13,"working":[{"label":"variable_debt","value":"£840k"},{"label":"rate_sd","value":"0.8%"},{"label":"bad_rate_rise = rate_sd × 1.65","value":"1.3%"},{"label":"bad_year_hit = variable_debt × bad_rate_rise","value":"£11k"},{"label":"risk_sd = variable_debt × rate_sd","value":"£6.6k"},{"label":"other_risks_sd","value":"£106k"},{"label":"farm_sd = √(risk_sd² + other_risks_sd²)","value":"£106k"},{"label":"expected_profit","value":"£85k"},{"label":"bad_year_profit = expected_profit − 1.65 × farm_sd","value":"−£90k"},{"label":"loss_years = 20 × Φ(−expected_profit ÷ farm_sd)","value":"4 in 20"}]}]'::jsonb);
